solutionCodeJson.code:
// Given — the business rules catalogue of GymPass (read only).
const BUSINESS_RULES = [
  { id: 'BR-01', statement: 'A member may not hold two bookings whose class times overlap.' },
  {
    id: 'BR-02',
    statement: 'If a member does not show up for 3 booked classes in one calendar month, the member cannot book any class for the next 7 days.',
  },
  { id: 'BR-03', statement: 'A booking can be cancelled free of charge until 2 hours before the class starts.' },
  {
    id: 'BR-04',
    statement: 'The price of a day pass bought for a member’s guest is 50% of the standard day-pass price.',
  },
  {
    id: 'BR-05',
    statement: 'Every group class takes place in one room, and the capacity of the class is the capacity of that room.',
  },
  {
    id: 'BR-06',
    statement: 'A member who checks in more than 15 minutes after the class has started is counted as a no-show.',
  },
];

// B. Actor table and use case table.
const ACTORS = [
  {
    name: 'Member',
    description: 'A student or staff member with a GymPass account who buys plans, books classes and checks in at the entrance.',
  },
  {
    name: 'Trainer',
    description: 'A fitness trainer who publishes the weekly class schedule and records the attendance of each class.',
  },
  {
    name: 'Front-desk Staff',
    description: 'Staff at the reception desk who sell day passes to walk-in guests and replace lost cards.',
  },
  {
    name: 'Manager',
    description: 'The fitness centre manager who sets plan and day-pass prices and reads occupancy reports.',
  },
  {
    name: 'E-wallet',
    description: 'External campus payment service that executes plan payments and returns the payment result.',
  },
  {
    name: 'Turnstile Controller',
    description: 'External device at the entrance that sends scanned QR codes and opens the turnstile on GymPass approval.',
  },
  {
    name: 'Notification Service',
    description: 'External university service that delivers the class reminders sent by GymPass.',
  },
];
const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Buy Membership Plan',
    actors: ['Member'],
    description: 'The member chooses a monthly, semester or yearly plan and buys it online.',
  },
  {
    id: 'UC-02',
    name: 'Make Payment',
    actors: ['E-wallet'],
    description: 'Included in buying a plan: the amount is charged through the e-wallet and the result recorded.',
  },
  {
    id: 'UC-03',
    name: 'Book a Class',
    actors: ['Member'],
    description: 'A member with an active plan reserves a seat in a scheduled group class.',
  },
  {
    id: 'UC-04',
    name: 'Join Class Waitlist',
    actors: [],
    description: 'Optional extension of booking: when the class is full the member joins its waitlist.',
  },
  {
    id: 'UC-05',
    name: 'Cancel Booking',
    actors: ['Member'],
    description: 'The member cancels a booking free of charge until two hours before the class.',
  },
  {
    id: 'UC-06',
    name: 'Check In at Entrance',
    actors: ['Member', 'Turnstile Controller'],
    description: 'The member scans a QR code at the turnstile and GymPass answers open or refuse.',
  },
  {
    id: 'UC-07',
    name: 'Publish Class Schedule',
    actors: ['Trainer'],
    description: 'The trainer publishes the classes of the coming week with room, time and capacity.',
  },
  {
    id: 'UC-08',
    name: 'Record Attendance',
    actors: ['Trainer'],
    description: 'The trainer marks which booked members attended a class and which did not show up.',
  },
  {
    id: 'UC-09',
    name: 'Sell Day Pass',
    actors: ['Front-desk Staff'],
    description: 'Front-desk staff sell a one-day pass to a walk-in guest at the reception desk.',
  },
  {
    id: 'UC-10',
    name: 'Replace Lost Card',
    actors: ['Front-desk Staff'],
    description: 'Front-desk staff block a lost membership card and issue a new card to the member.',
  },
  {
    id: 'UC-11',
    name: 'Set Prices',
    actors: ['Manager'],
    description: 'The manager sets the prices of membership plans and of the day pass.',
  },
  {
    id: 'UC-12',
    name: 'View Occupancy Reports',
    actors: ['Manager'],
    description: 'The manager reads how full classes and the gym floor were per day and per week.',
  },
  {
    id: 'UC-13',
    name: 'Send Class Reminder',
    actors: ['Notification Service'],
    description: 'One hour before a class, every booked member is reminded through the notification service.',
  },
];

// D1. Wiegers' five types: Fact · Constraint · Action enabler · Inference · Computation.
const BR_TYPES = {
  'BR-01': 'Constraint',  // restricts what may happen
  'BR-02': 'Action enabler',  // IF condition THEN the system acts (blocks)
  'BR-03': 'Constraint',
  'BR-04': 'Computation',  // a formula
  'BR-05': 'Fact',  // a statement that is simply true
  'BR-06': 'Inference',  // IF … THEN a new fact (no-show) is derived
};

// D2. One requirement per statement, system perspective, no ambiguous words, every rule of the spec covered.
const FRS = [
  'The system shall display, for a selected date, every class with its trainer, room, start time and number of free seats.',
  'The system shall refuse a booking from a member who is blocked because of 3 no-shows in the calendar month and shall show the date when the block ends.',
  'The system shall refuse a booking whose class time overlaps another booking of the same member.',
  'The system shall create a confirmed booking and decrease the free seats of the class by one when a member confirms a booking.',
  'The system shall offer to place the member on the waitlist of a class that has no free seat.',
  'The system shall give a freed seat to the first member on the waitlist of that class.',
  'The system shall allow a member to cancel a booking free of charge until 2 hours before the class starts.',
  'The system shall send a booking confirmation to the member through the Notification Service.',
];

